frame.store("people_in_groups", { let __signature_1240 = Signature { name: "people_in_groups".into(), positional: vec!["text".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1242 = Value::dict(); __attrs_1242.dict_set(Value::from("__doc__"), Value::from("How many people the groups named in the line add up to, or None when it names none.\n\n    Every group counts: \"4 adults and 3 kids\" is seven, \"3 kids and 2 adults\" is five, and a\n    line with one group (\"for 4 people\", \"6 kids\") is that group. A child is a person at the\n    table too, so the total is what the shopping and the pan are for - the note that children eat\n    a little less belongs in the answer, not in a count that quietly leaves them out.\n    "))?; __attrs_1242.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_1243 = Value::dict(); __attrs_1242.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1239 = Frame::module(frame.globals.clone()); let mut __function_1241 = NativeFunction::qualified_with_origin("people_in_groups".into(), "people_in_groups".into(), "bot.knowledge.units".into(), __attrs_1242, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/units.py", first: 1367, last: 1380, qualname: "people_in_groups" }, closure: __closure_1239.clone(), freevars: vec![] }, move |rt, args| __py_36::people_in_groups(rt, __closure_1239.clone(), &__signature_1240, args)); __function_1241 })?;
